func CoerceRecordToBSONDoc(rec map[string]any, colTypes map[string]string) (bson.M, error) {
	doc := make(bson.M, len(rec))
	for k, v := range rec {
		if v == nil {
			doc[k] = nil
			continue
		}
		dt := ""
		if colTypes != nil {
			dt = colTypes[k]
		}
		coerced, err := CoerceToBSONValue(v, dt, "")
		if err != nil {
			return nil, fmt.Errorf("field %q (%s): %w", k, dt, err)
		}
		doc[k] = coerced
	}
	return doc, nil
}

